<canvas id="canvas"></canvas><div class="hud">LAYOUT <b id="h-mode">GRID</b><br>SIGNALS <b id="h-sig">24</b><br>GAIN <b id="h-gain">1.20</b><br><span class="sub">SYNC</span> <b id="h-sync">0.50</b></div><?php $interactionHints=[['type'=>'click','label'=>'ping'],['type'=>'drag','label'=>'tune']];require_once __DIR__ . '/includes/interaction-hints.php';?>
<div id="controls" class="drawer-controls"><div><div class="btn-row"><button class="control-btn active" data-mode="grid">GRID</button><button class="control-btn" data-mode="radar">RADAR</button><button class="control-btn" data-mode="stream">STREAM</button></div></div><div><div class="slider-row"><span class="slider-label">SIGNALS</span><input type="range" id="sl-sig" min="8" max="48" value="24"><span class="slider-value" id="sv-sig">24</span></div></div><div><div class="slider-row"><span class="slider-label">GAIN</span><input type="range" id="sl-gain" min="40" max="220" value="120"><span class="slider-value" id="sv-gain">1.20</span></div></div><div><div class="btn-row"><button class="control-btn active" id="btn-run">RUN</button><button class="control-btn" id="btn-sync">SYNC</button></div></div></div><?php require_once __DIR__ . '/includes/drawer-controls.php';?>
<script>(function(){var c=document.getElementById('canvas'),x=c.getContext('2d'),W,H,D=1,mode='grid',signals=24,gain=1.2,run=true,t=0,pings=[];var hm=document.getElementById('h-mode'),hs=document.getElementById('h-sig'),hg=document.getElementById('h-gain'),hy=document.getElementById('h-sync'),ss=document.getElementById('sl-sig'),sg=document.getElementById('sl-gain'),vs=document.getElementById('sv-sig'),vg=document.getElementById('sv-gain');function resize(){D=Math.min(2,devicePixelRatio||1);W=c.width=Math.floor(innerWidth*D);H=c.height=Math.floor(innerHeight*D);c.style.width=innerWidth+'px';c.style.height=innerHeight+'px'}function hud(){hm.textContent=mode.toUpperCase();hs.textContent=signals;vs.textContent=signals;hg.textContent=gain.toFixed(2);vg.textContent=gain.toFixed(2);hy.textContent=(.5+.5*Math.sin(t*.7)).toFixed(2)}function panel(px,py,pw,ph,i){x.strokeStyle='rgba(0,245,212,.16)';x.strokeRect(px,py,pw,ph);x.save();x.beginPath();x.rect(px,py,pw,ph);x.clip();x.globalCompositeOperation='lighter';for(var k=0;k<signals/3;k++){var q=(k+i*7)%signals,yy=py+ph*(.5+.36*Math.sin(t*(.8+q*.02)+q));x.strokeStyle=q%2?'rgba(123,44,191,.38)':'rgba(0,245,212,.42)';x.beginPath();for(var xx=0;xx<pw;xx+=8*D){var y=yy+Math.sin(xx*.018+t*2+q)*ph*.08*gain;if(xx===0)x.moveTo(px+xx,y);else x.lineTo(px+xx,y)}x.stroke()}x.restore()}function draw(){if(run)t+=.018;x.fillStyle='rgba(10,10,15,.26)';x.fillRect(0,0,W,H);x.strokeStyle='rgba(0,245,212,.05)';for(var gx=0;gx<14;gx++){x.beginPath();x.moveTo(gx*W/14,0);x.lineTo(gx*W/14,H);x.stroke()}if(mode==='grid'){var m=42*D,w=(W-m*4)/3,h=(H-m*3)/2;for(var j=0;j<2;j++)for(var i=0;i<3;i++)panel(m+i*(w+m),m+j*(h+m),w,h,i+j*3)}else{var cx=W/2,cy=H/2,r=Math.min(W,H)*.34;x.globalCompositeOperation='lighter';for(var i=0;i<signals;i++){var a=i/signals*Math.PI*2+(mode==='radar'?t:Math.sin(t+i)*.2),rr=r*(.25+.72*((i*37)%signals)/signals);var px=cx+Math.cos(a)*rr,py=cy+Math.sin(a)*rr;x.strokeStyle=i%2?'rgba(123,44,191,.36)':'rgba(0,245,212,.42)';x.beginPath();x.arc(px,py,(2+Math.sin(t*3+i)*1.5)*D,0,Math.PI*2);x.stroke();if(mode==='stream'){x.beginPath();x.moveTo(cx,cy);x.lineTo(px,py);x.stroke()}}x.globalCompositeOperation='source-over'}for(var p=pings.length-1;p>=0;p--){var o=pings[p];o.l+=.025;x.strokeStyle='rgba(0,245,212,'+Math.max(0,.7-o.l)+')';x.beginPath();x.arc(o.x*D,o.y*D,o.l*220*D,0,Math.PI*2);x.stroke();if(o.l>1)pings.splice(p,1)}hud();requestAnimationFrame(draw)}c.onpointerdown=e=>{pings.push({x:e.clientX,y:e.clientY,l:0});if(typeof SFX!=='undefined')SFX.play('ripple',100)};c.onpointermove=e=>{if(e.buttons){gain=Math.max(.4,Math.min(2.2,gain+(e.movementY||0)*-.005));sg.value=Math.round(gain*100);}};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;document.querySelectorAll('[data-mode]').forEach(q=>q.classList.toggle('active',q===b));if(typeof SFX!=='undefined')SFX.play('toggle')});ss.oninput=()=>{signals=+ss.value;hud()};sg.oninput=()=>{gain=+sg.value/100;hud()};document.getElementById('btn-run').onclick=e=>{run=!run;e.currentTarget.classList.toggle('active',run);if(typeof SFX!=='undefined')SFX.play('toggle')};document.getElementById('btn-sync').onclick=()=>{t=0;pings.push({x:innerWidth/2,y:innerHeight/2,l:0});if(typeof SFX!=='undefined')SFX.play('success')};addEventListener('resize',resize);resize();draw()})();</script><?php require_once __DIR__ . '/includes/sfx.php';require_once __DIR__ . '/includes/page-end.php';?></body></html>